[project]
name = "tools"
version = "0.1.0"
description = "Scripts that gather the data in ../data"
requires-python = ">=3.14"
dependencies = []

[build-system]
requires = ["uv_build>=0.13.7,<0.14.0"]
build-backend = "uv_build"

[dependency-groups]
dev = [
    "ruff>=0.17.4",
]

[tool.ruff.lint]
extend-select = ["I", "UP", "B"]
--- next config ---
import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  agentRules: false,
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
};

export default nextConfig;
--- page ---
export default function Home() {
  return <main />;
}
--- gitignore ---
.env*
!.env.example
.DS_Store

